}

#app { position: fixed; inset: 0; }
#scene { position: absolute; inset: 0; width: 100%; height: 100%; display: block; outline: none; }

.hidden { display: none !important; }

/* ---------- Atmosphere overlays ---------- */
#vignette {
  position: absolute; inset: 0; pointer-events: none; z-index: 2;
  background:
    radial-gradient(ellipse at 50% 42%, transparent 38%, rgba(2, 2, 8, 0.55) 100%),
    linear-gradient(to bottom, rgba(4, 4, 10, 0.32), transparent 22%, transparent 76%, rgba(3, 3, 9, 0.5));
}

#damage-flash {
