}
.bust-label { font-family: var(--font-mono); font-size: 10px; letter-spacing: 0.4em; color: var(--danger); margin-bottom: 6px; animation: pulse 0.8s infinite; }
.bust-track { height: 5px; background: rgba(255, 59, 78, 0.15); border: 1px solid rgba(255, 59, 78, 0.4); }
#bust-fill { height: 100%; width: 0%; background: var(--danger); box-shadow: 0 0 12px var(--danger); }

.toast-stack {
  position: absolute; top: 17%; left: 50%; transform: translateX(-50%);
  display: flex; flex-direction: column; align-items: center; gap: 6px;
  width: 80%; pointer-events: none;
}
.toast {
  font-family: var(--font-mono); font-size: clamp(11px, 1.2vw, 14px); font-weight: 700;
  letter-spacing: 0.22em; text-transform: uppercase;
