.toast.bad { color: #ffd7dd; border-color: var(--danger); }
.toast.gold { color: var(--gold); border-color: var(--gold); }
.toast.out { animation: toastOut 0.4s ease forwards; }
@keyframes toastIn { from { opacity: 0; transform: translateY(-8px) scale(0.96); } to { opacity: 1; transform: none; } }
@keyframes toastOut { to { opacity: 0; transform: translateY(-10px) scale(0.97); } }

.hud-bottom {
  position: absolute; bottom: max(16px, env(safe-area-inset-bottom)); left: 0; right: 0;
  display: flex; justify-content: space-between; align-items: flex-end;
  padding: 0 clamp(16px, 3vw, 42px);
  pointer-events: none;
}

.map-panel { display: flex; flex-direction: column; gap: 7px; }
.map-frame {
  position: relative; width: clamp(130px, 14vw, 190px); aspect-ratio: 1;
  border-radius: 50%;
  background: rgba(4, 6, 12, 0.72);
  border: 1px solid rgba(120, 220, 255, 0.22);
  box-shadow: 0 0 30px rgba(0,0,0,0.6), inset 0 0 30px rgba(78, 240, 224, 0.06);
