  font-family: var(--font-mono); font-size: 9px; color: var(--cyan);
  text-shadow: 0 0 8px rgba(78,240,224,0.8);
}
.map-meta {
  display: flex; justify-content: space-between; gap: 10px;
  font-family: var(--font-mono); font-size: 8px; letter-spacing: 0.16em; color: var(--muted);
}
#cop-count { color: #ff8397; }

.speed-panel {
  position: relative; width: clamp(150px, 17vw, 230px); aspect-ratio: 1;
  filter: drop-shadow(0 0 18px rgba(0,0,0,0.55));
}
#speedo { width: 100%; height: 100%; display: block; }
.speed-readout {
  position: absolute; inset: 0; display: flex; flex-direction: column;
  align-items: center; justify-content: center; padding-top: 8%;
  pointer-events: none;
}
#speed-val {
  font-family: var(--font-mono); font-weight: 800;
  font-size: clamp(30px, 3.4vw, 46px); line-height: 1; color: #fff;
  text-shadow: 0 0 20px rgba(78, 240, 224, 0.5); font-variant-numeric: tabular-nums;
}
.speed-readout .unit { font-family: var(--font-mono); font-size: 8px; letter-spacing: 0.3em; color: var(--muted); margin-top: 4px; }
.gear {
  position: absolute; bottom: 16%; left: 50%; transform: translateX(-50%);
  font-family: var(--font-mono); font-size: 11px; font-weight: 700; color: var(--cyan);
  letter-spacing: 0.2em; text-shadow: 0 0 10px rgba(78,240,224,0.6);
