  white-space: nowrap; transition: opacity 1s;
}
.hint-key { color: #b9c8e2; border: 1px solid rgba(160,200,255,0.25); padding: 2px 5px; border-radius: 3px; font-size: 8px; }

/* ---------- Touch controls ---------- */
.touch-controls { display: none; }
.tbtn {
  pointer-events: auto; touch-action: none;
  appearance: none; border: 1px solid rgba(120, 220, 255, 0.28);
  background: rgba(8, 12, 22, 0.5); color: #d9f4ff;
  font-family: var(--font-mono); font-size: 11px; font-weight: 700; letter-spacing: 0.12em;
  border-radius: 50%; width: 62px; height: 62px;
  display: flex; align-items: center; justify-content: center;
  backdrop-filter: blur(4px);
  transition: background 0.1s, transform 0.1s;
}
.tbtn:active, .tbtn.on { background: rgba(78, 240, 224, 0.22); transform: scale(0.94); border-color: var(--cyan); }
.touch-left, .touch-right { position: absolute; bottom: max(18px, env(safe-area-inset-bottom)); display: flex; gap: 12px; }
.touch-left { left: max(16px, env(safe-area-inset-left)); }
.touch-right { right: max(16px, env(safe-area-inset-right)); }
.tbtn.gas { width: 76px; height: 76px; border-color: rgba(78, 240, 224, 0.5); color: var(--cyan); }
.tbtn.brake { width: 64px; height: 64px; align-self: flex-end; }
.tbtn.drift {
