  bottom: max(104px, calc(env(safe-area-inset-bottom) + 96px));
  width: 70px; height: 44px; border-radius: 22px; font-size: 9px;
}
.tbtn.drift:active { transform: translateX(-50%) scale(0.94); }
.tbtn.nitro {
  position: absolute; right: max(18px, env(safe-area-inset-right));
  bottom: max(112px, calc(env(safe-area-inset-bottom) + 104px));
  width: 58px; height: 40px; border-radius: 20px; font-size: 8px; color: var(--pink); border-color: rgba(255,45,120,0.45);
}

/* ---------- Modals ---------- */
#pause-screen, #over-screen { justify-content: center; align-items: center; background: rgba(3, 4, 9, 0.72); backdrop-filter: blur(7px); }
.modal {
  width: min(560px, 90vw); text-align: center;
  background: linear-gradient(180deg, rgba(12, 16, 28, 0.94), rgba(6, 8, 16, 0.96));
  border: 1px solid rgba(120, 220, 255, 0.18);
  padding: clamp(26px, 5vw, 52px);
  box-shadow: 0 30px 100px rgba(0,0,0,0.7), inset 0 1px 0 rgba(255,255,255,0.05);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 22px), calc(100% - 22px) 100%, 0 100%);
  animation: modalIn 0.3s cubic-bezier(0.2, 0.9, 0.3, 1.2) both;
