@keyframes modalIn { from { opacity: 0; transform: translateY(14px) scale(0.98); } to { opacity: 1; transform: none; } }
.modal-kicker { font-family: var(--font-mono); font-size: 10px; letter-spacing: 0.44em; color: var(--pink); margin-bottom: 10px; }
.modal h2 { margin: 0 0 8px; font-size: clamp(28px, 4vw, 46px); font-style: italic; letter-spacing: -0.02em; font-family: "Arial Black", Impact, sans-serif; text-transform: uppercase; }
.modal p { color: var(--muted); margin: 0 0 26px; font-size: 13px; }
.modal .cta { margin: 6px auto 12px; }
.ghost {
  appearance: none; background: none; border: 0; color: #6f7d9c; cursor: pointer;
  font-family: var(--font-mono); font-size: 10px; letter-spacing: 0.24em; text-transform: uppercase;
  padding: 10px 18px;
}
.ghost:hover { color: #fff; }
.over-modal h2 { color: #fff; }
.stats { display: grid; grid-template-columns: 1fr 1fr; gap: 1px; background: rgba(120, 220, 255, 0.12); margin: 24px 0; border: 1px solid rgba(120, 220, 255, 0.12); }
.stat { background: #0a0d18; padding: 16px 12px; display: flex; flex-direction: column; gap: 7px; }
.stat span { font-family: var(--font-mono); font-size: 8px; letter-spacing: 0.24em; color: var(--muted); }
.stat strong { font-family: var(--font-mono); font-size: 22px; color: #fff; font-variant-numeric: tabular-nums; }
.stat strong em { font-style: normal; font-size: 9px; color: var(--muted); letter-spacing: 0.14em; }
.new-best { font-family: var(--font-mono); font-size: 10px; letter-spacing: 0.3em; color: var(--gold); margin-bottom: 16px; text-shadow: 0 0 14px rgba(255,200,87,0.6); }

/* ---------- Loading ---------- */
.loading {
  position: absolute; inset: 0; z-index: 50; display: flex; align-items: center; justify-content: center;
  background: #05060b; transition: opacity 0.6s ease, visibility 0.6s;
}
