148: function snapCamera() {
149:   const fwd = player.forward;
150:   camPos.copy(player.pos).addScaledVector(fwd, -9.2).add(new THREE.Vector3(0, 4.1, 0));
151:   camLook.copy(player.pos).addScaledVector(fwd, 8).add(new THREE.Vector3(0, 1.35, 0));
152:   camera.position.copy(camPos);
153:   camera.lookAt(camLook);
154:   camera.fov = 62;
155:   camera.updateProjectionMatrix();
156: }
