158: function updateCamera(dt) {
159:   if (state === 'menu') {
160:     menuTime += dt;
161:     const drift = Math.sin(menuTime * 0.16) * 0.7;
162:     camPos.set(-7.6 + drift, 4.8 + Math.sin(menuTime * 0.4) * 0.25, -1.5);
163:     camLook.set(0.7, 1.05, -13.5);
164:     camera.position.lerp(camPos, 1 - Math.exp(-3 * dt));
165:     camera.lookAt(camLook);
166:     camera.fov = damp(camera.fov, 58, 3, dt);
167:     camera.updateProjectionMatrix();
168:     return;
169:   }
170: 
171:   if (state === 'over') {
172:     const a = performance.now() * 0.00016;
173:     tmpV.set(player.pos.x + Math.cos(a) * 13, 7.5, player.pos.z + Math.sin(a) * 13);
174:     camera.position.lerp(tmpV, 1 - Math.exp(-1.2 * dt));
175:     camera.lookAt(player.pos.x, 1.1, player.pos.z);
176:     return;
177:   }
178: 
179:   if (state === 'paused') return;
180: 
181:   const speedT = clamp(Math.abs(player.speed) / 48, 0, 1);
182:   const fwd = player.forward;
183:   const back = 9.1 + speedT * 2.8;
184:   const height = 4.0 + speedT * 0.9;
185:   tmpV.copy(player.pos).addScaledVector(fwd, -back).add(new THREE.Vector3(0, height, 0));
186:   tmpV.addScaledVector(player.right, -player.steer * 0.7);
187:   camPos.lerp(tmpV, 1 - Math.exp(-4.8 * dt));
188: 
189:   tmpV.copy(player.pos).addScaledVector(fwd, 6 + speedT * 10).add(new THREE.Vector3(0, 1.35, 0));
190:   camLook.lerp(tmpV, 1 - Math.exp(-7.5 * dt));
191: 
192:   const shake = fx.shake * 0.35 + (player.impact > 7 ? 0.16 : 0);
193:   camera.position.copy(camPos);
194:   if (shake > 0.001) {
195:     camera.position.x += rand(-shake, shake);
196:     camera.position.y += rand(-shake, shake) * 0.65;
197:     camera.position.z += rand(-shake, shake);
198:   }
199:   camera.lookAt(camLook);
200:   const fovTarget = 62 + speedT * 10 + (boostActive ? 5 : 0);
201:   camera.fov = damp(camera.fov, fovTarget, 4, dt);
202:   camera.updateProjectionMatrix();
203: }
