335:         for (let k = 0; k < 14; k++) {
336:           const spot = world.pickupSpots[Math.floor(Math.random() * world.pickupSpots.length)];
337:           if (Math.hypot(spot.x - player.pos.x, spot.z - player.pos.z) > 45) {
