363: /*  Playing update                                                    */
364: /* ------------------------------------------------------------------ */
365: function updatePlaying(dt) {
366:   gameTime += dt;
367:   crashCooldown = Math.max(0, crashCooldown - dt);
368:   nearMissCooldown = Math.max(0, nearMissCooldown - dt);
369: 
370:   const raw = input.playerInput();
371:   boostActive = raw.boost && raw.throttle > 0 && nitro > 1 && Math.abs(player.speed) > 2;
372:   if (boostActive) {
373:     nitro = Math.max(0, nitro - dt * 24);
374:     if (nitro <= 0.5) boostActive = false;
375:   } else {
376:     nitro = Math.min(100, nitro + dt * 8.5);
377:   }
378: 
379:   player.update(dt, { ...raw, boost: boostActive });
380: 
381:   const impact = collideWithWorld(player, world.colliders, CITY.bounds);
382:   if (impact > 8) {
383:     const dmg = (impact - 7) * 0.48;
384:     health -= dmg;
385:     hud.flashDamage();
386:     fx.addShake(clamp(impact * 0.05, 0.15, 1));
387:     fx.sparks(player.pos.clone().add(new THREE.Vector3(0, 0.9, 0)), Math.min(26, 5 + impact));
388:     audio.crash(clamp(impact / 22, 0.2, 1.2));
389:     if (impact > 19 && crashCooldown <= 0) {
390:       crashCooldown = 1.2;
391:       hud.toast('HEAVY IMPACT', 'bad');
392:     }
393:     heat = Math.min(100, heat + impact * 0.12);
394:   }
395: 
396:   // traffic collisions
397:   for (const car of traffic.cars) {
398:     const hit = collideCars(player, car.body);
399:     if (hit > 2.2) {
400:       const mid = new THREE.Vector3((player.pos.x + car.body.pos.x) / 2, 0.85, (player.pos.z + car.body.pos.z) / 2);
401:       fx.sparks(mid, Math.min(18, 4 + hit));
402:       fx.addShake(clamp(hit * 0.04, 0.08, 0.7));
403:       audio.crash(clamp(hit / 24, 0.15, 1));
404:       health -= hit * 0.28;
405:       heat = Math.min(100, heat + 2.4);
406:       traffic.hit(car, hit, player.pos.x, player.pos.z);
407:       hud.flashDamage();
408:     }
409:   }
410:   traffic.update(dt, player.pos);
411: 
412:   police.onHitPlayer = (rel) => {
413:     health -= clamp(rel * 0.62, 2, 26);
414:     heat = Math.min(100, heat + 2.2);
415:     fx.addShake(clamp(rel * 0.05, 0.2, 1.1));
416:     hud.flashDamage();
417:     if (rel > 12 && crashCooldown <= 0) {
418:       crashCooldown = 0.9;
419:       hud.toast('RAMMED', 'bad');
420:     }
421:   };
422:   police.onTakedown = () => {
423:     takedowns++;
424:     score += 800;
425:     heat = Math.min(100, heat + 7);
426:     hud.toast('TAKEDOWN +800', 'gold');
427:     fx.addShake(0.7);
428:   };
429: 
430:   police.update(dt, wanted);
431: 
432:   // near misses + cop scan
433:   let nearest = Infinity;
434:   for (const cop of police.cops) {
435:     if (cop.disabled) continue;
436:     const d = cop.body.pos.distanceTo(player.pos);
437:     nearest = Math.min(nearest, d);
438:     if (d < 6.5 && d > 2.6 && Math.abs(player.speed) > 17 && nearMissCooldown <= 0) {
439:       nearMissCooldown = 2.5;
440:       score += 60;
441:       heat = Math.min(100, heat + 0.6);
442:       if (Math.random() < 0.6) hud.toast('NEAR MISS +60', '');
443:     }
444:   }
445: 
446:   updatePickups(dt);
447: 
448:   // wanted / heat
449:   const copsActive = police.activeCount;
450:   if (escapeTimer > 0) {
451:     escapeTimer -= dt;
452:     if (escapeTimer <= 0) {
453:       heat = 12;
454:       hud.toast('NEW PURSUIT INBOUND', 'bad');
455:       police.spawnNearPlayer();
456:       police.spawnNearPlayer();
457:     }
458:   } else if (heat > 0) {
459:     heat = Math.min(100, heat + dt * (0.32 + wanted * 0.11));
460:     if (Math.abs(player.speed) > 26 && nearest < 70) heat = Math.min(100, heat + dt * 0.4);
461:   }
462: 
463:   if (heat > 0 && escapeTimer <= 0) {
464:     if (copsActive === 0 || nearest > 95) {
465:       evadeTimer += dt;
466:       if (evadeTimer > 3.2) {
467:         heat = Math.max(0, heat - dt * 10);
468:         if (!evadeToast) {
469:           evadeToast = true;
470:           hud.toast('LOSING THEM', '');
471:         }
472:       }
473:     } else {
474:       evadeTimer = 0;
475:       evadeToast = false;
476:     }
477:   }
478: 
479:   const newWanted = heat <= 0 ? 0 : clamp(Math.ceil(heat / 20), 1, 5);
480:   if (newWanted !== wanted) {
481:     if (newWanted > wanted) {
482:       hud.toast(`WANTED LEVEL ${newWanted}`, 'bad');
483:       audio.click();
484:       if (newWanted >= 3) hud.toast('AIR UNIT DEPLOYED', 'bad');
485:     }
486:     wanted = newWanted;
487:   }
488: 
489:   if (heat <= 0 && escapeTimer <= 0) {
490:     heat = 0;
491:     escapeTimer = 6.5;
492:     evadeTimer = 0;
493:     evadeToast = false;
494:     score += 1200;
495:     hud.toast('CLEAN GETAWAY +1200', 'gold');
496:   }
497: 
498:   // busted check
499:   if (wanted > 0 && copsActive > 0 && nearest < 7 && Math.abs(player.speed) < 1.6) {
500:     bustProgress += dt / 3.4;
501:     if (bustProgress > 0.15 && Math.random() < dt * 2) hud.toast('KEEP MOVING', 'bad');
502:   } else {
503:     bustProgress = Math.max(0, bustProgress - dt * 1.1);
504:   }
505:   if (bustProgress >= 1) {
506:     endRun(true);
507:     return;
508:   }
509: 
510:   // score
511:   score += dt * (8 + wanted * 5 + Math.abs(player.speed) * 0.15);
512:   topSpeed = Math.max(topSpeed, Math.abs(player.speed) * 3.6);
513: 
514:   if (health <= 0) {
515:     endRun(false);
516:     return;
517:   }
518: 
519:   fx.update(dt, player, raw);
520:   world.animate(dt);
521:   peds.update(dt, player.pos, Math.abs(player.speed));
522: 
523:   hud.update(dt, {
524:     player,
525:     wanted,
526:     heat,
527:     health,
528:     nitro,
529:     score,
530:     time: gameTime,
531:     cops: copsActive,
532:     copBlips: police.blips,
533:     pickups: world.pickups,
534:     helicopter: police.heli ? police.heli.pos : null,
535:     bustProgress,
536:     boosting: boostActive,
537:     maxSpeed: player.maxSpeed,
538:   });
539: 
540:   audio.update(dt, {
541:     speed: player.speed,
542:     throttle: raw.throttle,
543:     drifting: raw.handbrake || player.slip > 4,
544:     siren: nearest === Infinity ? 0 : clamp(1 - nearest / 120, 0, 1),
545:     active: true,
546:   });
547: }
