552: function updateShadows() {
553:   let i = 0;
554:   const place = (pos, heading, scale = 1) => {
555:     if (i >= 80) return;
556:     shadowDummy.position.set(pos.x, 0.055, pos.z);
557:     shadowDummy.rotation.set(0, heading, 0);
558:     shadowDummy.scale.set(scale, 1, scale);
559:     shadowDummy.updateMatrix();
560:     shadows.setMatrixAt(i++, shadowDummy.matrix);
561:   };
562:   place(player.pos, player.heading, 1);
563:   for (const cop of police.cops) place(cop.body.pos, cop.body.heading, 1.05);
564:   for (const car of traffic.cars) place(car.body.pos, car.body.heading, 1);
565:   const zero = new THREE.Matrix4().makeScale(0, 0, 0);
566:   for (; i < 80; i++) shadows.setMatrixAt(i, zero);
567:   shadows.instanceMatrix.needsUpdate = true;
568: }
