590: function frame(now) {
591:   requestAnimationFrame(frame);
592:   const dt = Math.min(0.05, Math.max(0.0001, (now - last) / 1000));
593:   last = now;
594: 
595:   if (state === 'menu') {
596:     updateMenu(dt);
597:   } else if (state === 'playing') {
598:     updatePlaying(dt);
599:     updateCamera(dt);
600:     updateShadows();
601:   } else if (state === 'paused') {
602:     updateCamera(dt);
603:     updateShadows();
604:   } else if (state === 'over') {
605:     fx.update(dt, null, null);
606:     world.animate(dt);
607:     updateCamera(dt);
608:     updateShadows();
609:   }
610: 
611:   renderer.render(scene, camera);
612: }
