import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: false, args: ['--no-sandbox','--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader'] });
const page = await browser.newPage({ viewport: { width: 640, height: 480 } });
page.on('pageerror', e => console.log('PAGEERROR', e.message));
page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE', m.text()); });
await page.goto('http://localhost:3002', { waitUntil: 'load' });
await page.waitForTimeout(3000);
console.log('loading', await page.evaluate(() => ({cls: document.getElementById('loading').className, vis: getComputedStyle(document.getElementById('loading')).visibility, op: getComputedStyle(document.getElementById('loading')).opacity})));
await page.click('#start-btn');
await page.waitForTimeout(1200);
console.log('start', await page.evaluate(() => ({stats: window.__neon.stats, pos: window.__neon.player.pos.toArray().map(v=>+v.toFixed(2)), cops: window.__neon.police.cops.map(c=>({x:+c.body.pos.x.toFixed(1),z:+c.body.pos.z.toFixed(1),d:+c.body.pos.distanceTo(window.__neon.player.pos).toFixed(1),disabled:c.disabled}))})));
await page.keyboard.down('w');
for (let i = 0; i < 8; i++) {
  await page.waitForTimeout(1000);
  console.log('t' + i, await page.evaluate(() => ({stats: window.__neon.stats, pos: window.__neon.player.pos.toArray().map(v=>+v.toFixed(2)), speed:+window.__neon.player.speed.toFixed(2), copD: window.__neon.police.cops.map(c=>+c.body.pos.distanceTo(window.__neon.player.pos).toFixed(1)), health: +window.__neon.stats.health.toFixed(1)})));
}
await page.keyboard.up('w');
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/drive-test.png', timeout: 60000 });
// Force heat 5 and see helicopter spawn
await page.evaluate(() => window.__neon.setHeat(100));
await page.waitForTimeout(2500);
console.log('heat5', await page.evaluate(() => ({stats: window.__neon.stats, heli: !!window.__neon.police.heli, cops: window.__neon.police.cops.length})));
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/heat5-test.png', timeout: 60000 });
// Wreck the car to verify game-over flow
await page.evaluate(() => window.__neon.setHealth(0));
await page.waitForTimeout(2500);
console.log('over', await page.evaluate(() => ({state: window.__neon.stats.state, overHidden: document.getElementById('over-screen').classList.contains('hidden'), hudHidden: document.getElementById('hud').classList.contains('hidden')})));
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/over-test.png', timeout: 60000 });
await browser.close();

