/* ---------- Responsive ---------- */
@media (max-width: 900px) {
  .screen { padding: 26px; align-items: flex-end; justify-content: flex-start; }
  .start-side { display: none; }
  .brand-title { font-size: clamp(56px, 16vw, 96px); }
  .start-blurb { display: none; }
  .controls-grid { display: none; }
  .cta { margin-top: 26px; padding: 16px 54px 16px 30px; }
  .start-foot { margin-top: 22px; }
  .hud-top { gap: 10px; }
  .wanted-block { min-width: 0; }
  .stars { gap: 1px; }
  .star { font-size: 17px; }
  .score-block { min-width: 0; }
  .bar-row { width: 112px; }
  .bar-name { width: 30px; font-size: 7px; }
  .run-block { position: absolute; left: 50%; transform: translateX(-50%); top: max(18px, env(safe-area-inset-top)); }
  .run-timer { font-size: 18px; }
  .district { display: none; }
  .hint-bar { display: none; }
  .hud-bottom { bottom: max(12px, env(safe-area-inset-bottom)); }
  .map-frame { width: 108px; }
  .map-meta { display: none; }
  .speed-panel { width: 118px; }
  #speed-val { font-size: 27px; }
  .speed-readout .unit { font-size: 6px; }
  .gear { display: none; }
  .touch-controls { display: block; position: absolute; inset: 0; pointer-events: none; }
  .hud-bottom { bottom: 150px; }
  .map-frame { width: 96px; }
  .speed-panel { width: 100px; }
  .toast-stack { top: 14%; }
}

@media (max-width: 560px) {
  .brand-title { font-size: 15vw; }
  .start-content { padding-bottom: 8px; }
  .star { font-size: 14px; }
  .score-value { font-size: 16px; }
  .run-timer { font-size: 15px; }
  .hud-top { padding-left: 12px; padding-right: 12px; }
  .hud-bottom { padding-left: 12px; padding-right: 12px; bottom: 140px; }
  .map-frame { width: 84px; }
  .speed-panel { width: 88px; }
  #speed-val { font-size: 23px; }
  .bars { margin-top: 5px; }
  .bar-row { width: 96px; }
  .touch-left, .touch-right { bottom: max(14px, env(safe-area-inset-bottom)); }
  .tbtn { width: 56px; height: 56px; }
  .tbtn.gas { width: 68px; height: 68px; }
  .tbtn.brake { width: 58px; height: 58px; }
  .tbtn.drift { bottom: max(88px, calc(env(safe-area-inset-bottom) + 82px)); width: 64px; height: 38px; }
  .tbtn.nitro { bottom: max(94px, calc(env(safe-area-inset-bottom) + 88px)); width: 54px; height: 36px; }
}

@media (max-height: 520px) and (orientation: landscape) {
  .brand-title { font-size: 64px; }
  .brand-sub { margin-top: 8px; }
  .cta { margin-top: 12px; padding: 12px 46px 12px 26px; font-size: 14px; }
  .start-foot { margin-top: 12px; }
  .controls-grid, .start-blurb, .start-side { display: none; }
  .screen { padding: 20px 32px; align-items: center; }
  .hud-bottom { bottom: 10px; }
  .map-frame { width: 92px; }
  .speed-panel { width: 96px; }
  .touch-controls { display: block; }
  .hud-bottom { bottom: 120px; }
  .touch-left, .touch-right { bottom: 12px; }
}
