  const out = {};
  for (const sel of els) { const e = document.querySelector(sel); if (!e) continue; const r = e.getBoundingClientRect(); out[sel] = {x:+r.x.toFixed(0),y:+r.y.toFixed(0),w:+r.width.toFixed(0),h:+r.height.toFixed(0),vis:getComputedStyle(e).display}; }
